<script setup lang="ts">
import { computed, ref } from "vue";
import { http } from "@/utils/http";
type Parameter = Record<string, any>; const rows = ref<Parameter[]>([]); const loading = ref(false); const error = ref(""); const query = ref(""); const source = ref(""); const detail = ref<any>(false); const filtered = computed(() => rows.value.filter(row => (!query.value || JSON.stringify(row).toLowerCase().includes(query.value.toLowerCase())) && (!source.value || row.source === source.value)));
async function load() { loading.value = true; try { const result: any = await http.get("/platform/parameters"); rows.value = Array.isArray(result) ? result : (result?.content || result?.items || []); } catch (e: any) { error.value = e?.response?.data?.detail || "平台参数接口尚未接入"; } finally { loading.value = false; } }
load();
</script>
<template><main class="p-4 md:p-6"><div class="flex justify-between items-start mb-6"><div><h1 class="text-2xl font-semibold">参数</h1><p class="mt-1 text-[var(--el-text-color-secondary)]">这里管理平台/运行时配置，不是任意数据库字段编辑器。</p></div><el-button :loading="loading" @click="load">刷新</el-button></div><el-alert v-if="error" :title="error" type="warning" show-icon :closable="false" class="mb-4"/><div class="flex flex-wrap gap-3 mb-4"><el-input v-model="query" clearable placeholder="搜索参数 Key 或名称" class="max-w-sm"/><el-select v-model="source" clearable placeholder="来源"><el-option label="默认值" value="DEFAULT"/><el-option label="配置文件" value="FILE"/><el-option label="数据库" value="DATABASE"/><el-option label="环境变量" value="ENVIRONMENT"/></el-select></div><el-skeleton v-if="loading" :rows="8" animated/><el-card v-else shadow="never"><el-empty v-if="!filtered.length" description="暂无平台参数；后端参数目录接入后可在此管理"/><el-table v-else :data="filtered" stripe><el-table-column prop="key" label="Key" min-width="240"/><el-table-column prop="displayName" label="显示名称" min-width="180"/><el-table-column prop="subsystem" label="子系统" width="140"/><el-table-column label="Effective Value" min-width="180"><template #default="{ row }">{{ row.sensitive ? '已配置' : (row.effectiveValue ?? row.value ?? '—') }}</template></el-table-column><el-table-column prop="source" label="来源" width="140"/><el-table-column prop="dataType" label="类型" width="120"/><el-table-column prop="scope" label="Scope" width="130"/><el-table-column prop="restartRequired" label="需重启" width="110"/><el-table-column label="操作" width="80"><template #default="{ row }"><el-button link @click="detail = row">查看</el-button></template></el-table-column></el-table></el-card><el-drawer v-model="detail" title="参数详情" size="480px"><el-descriptions v-if="detail" :column="1" border><el-descriptions-item label="Key">{{ detail.key }}</el-descriptions-item><el-descriptions-item label="描述">{{ detail.description || '—' }}</el-descriptions-item><el-descriptions-item label="当前值">{{ detail.sensitive ? '已配置（遮罩）' : detail.effectiveValue || '—' }}</el-descriptions-item><el-descriptions-item label="默认值">{{ detail.sensitive ? '已隐藏' : detail.defaultValue || '—' }}</el-descriptions-item><el-descriptions-item label="来源优先级">环境变量 → 配置文件 → 数据库 → 默认值</el-descriptions-item><el-descriptions-item label="受影响服务">{{ detail.affectedSubsystem || '由后端提供' }}</el-descriptions-item></el-descriptions></el-drawer></main></template>
